// TickChildren ticks child state machines (W3C SCXML 6.4).
// Port of Rust do_tick_children().
func (p *EmptyFinalizeUpdatesTheLocationPolicy) TickChildren(engine *sce.Engine[EmptyFinalizeUpdatesTheLocationState, EmptyFinalizeUpdatesTheLocationEvent]) {
	if !p.pendingDoneInvokeInvEmpty && p.childInvEmpty != nil {
		child := p.childInvEmpty
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv_empty", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv_empty", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeInvEmpty {
			p.pendingDoneInvokeInvEmpty = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("inv_empty", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeInvAbsent && p.childInvAbsent != nil {
		child := p.childInvAbsent
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv_absent", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv_absent", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeInvAbsent {
			p.pendingDoneInvokeInvAbsent = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("inv_absent", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeInvUnmatched && p.childInvUnmatched != nil {
		child := p.childInvUnmatched
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv_unmatched", engine)
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "inv_unmatched", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeInvUnmatched {
			p.pendingDoneInvokeInvUnmatched = true
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("inv_unmatched", child.DonedataAtFinal(), engine)
		}
	}
}


// DeliverToChildSession delivers an event addressed to a child's published
// location (W3C SCXML C.1).
//
// The parent mints `parentSession.invokeId` for each child and that id is what
// the child's `_ioprocessors` entry names, so a <send> whose target decodes to
// one of them is addressed to that child rather than to this machine. A false
// return means the address names no live child of ours and the event takes the
// normal external path — the routing half of C.1 is what makes the published
// location a usable target rather than a string that merely compares equal.
func (p *EmptyFinalizeUpdatesTheLocationPolicy) DeliverToChildSession(childSessionID, eventName, eventData string) bool {
	if childSessionID == "" {
		return false
	}
	if cs, ok := p.activeInvokes["inv_empty"]; ok && cs.SessionID == childSessionID {
		if p.childInvEmpty != nil {
			p.childInvEmpty.RaiseExternalByName(eventName, eventData)
			return true
		}
	}
	if cs, ok := p.activeInvokes["inv_absent"]; ok && cs.SessionID == childSessionID {
		if p.childInvAbsent != nil {
			p.childInvAbsent.RaiseExternalByName(eventName, eventData)
			return true
		}
	}
	if cs, ok := p.activeInvokes["inv_unmatched"]; ok && cs.SessionID == childSessionID {
		if p.childInvUnmatched != nil {
			p.childInvUnmatched.RaiseExternalByName(eventName, eventData)
			return true
		}
	}
	return false
}

// ExecuteFinalizeForChildEvent executes finalize for events from invoked children (W3C SCXML 6.5).
func (p *EmptyFinalizeUpdatesTheLocationPolicy) ExecuteFinalizeForChildEvent(eventWithMeta *sce.EventWithMetadata[EmptyFinalizeUpdatesTheLocationEvent], engine *sce.Engine[EmptyFinalizeUpdatesTheLocationState, EmptyFinalizeUpdatesTheLocationEvent]) {
	if eventWithMeta.Metadata.Origin == "" {
		return
	}

	origin := eventWithMeta.Metadata.Origin
	var finalizeScript string
	for _, childSession := range p.activeInvokes {
		if childSession.SessionID == origin && childSession.FinalizeScript != "" {
			finalizeScript = childSession.FinalizeScript
			break
		}
	}

	if finalizeScript != "" {
		p.ensureScriptEngine()
		se := p.ScriptEngine
		if se != nil {
			eventName := p.GetEventName(eventWithMeta.Event)
			// W3C SCXML 6.4: `<finalize>` binds the child's event so the
			// handler can read it, and the rung that binding chose is not
			// this site's to report. The parent's own dequeue already
			// counted the delivery — see `NotePayloadReading` — and counting
			// it again here would double every payload that reaches a
			// document with an `<invoke>`. Discarded deliberately, and named
			// rather than left to a bare `_`.
			_, _ = se.SetCurrentEvent(
				p.SessionID,
				sce.SetCurrentEventArgs{
					Name:       eventName,
					Data:       eventWithMeta.Metadata.Data,
					Type:       "external",
					SendID:     eventWithMeta.Metadata.SendID,
					Origin:     eventWithMeta.Metadata.Origin,
					OriginType: eventWithMeta.Metadata.OriginType,
					InvokeID:   eventWithMeta.Metadata.InvokeID,
				},
			)
			_ = se.ExecuteScript(p.SessionID, finalizeScript)
		}
	}
}

